import{z as l,x as i,o as e,c as d,q as r,j as n,D as a,d as B,s as o,S as A,b as s}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"计划空间与枚举","description":"","frontmatter":{"title":"计划空间与枚举","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/qo-plan-space.md","filePath":"cs/qo-plan-space.md","lastUpdated":1791063341000}'),p={name:"cs/qo-plan-space.md"};function m(C,E,c,D,h,u){const t=i("Mermaid");return e(),d("div",null,[E[2]||(E[2]=r('<h1 id="计划空间与枚举" tabindex="-1">计划空间与枚举 <a class="header-anchor" href="#计划空间与枚举" aria-label="Permalink to &quot;计划空间与枚举&quot;">​</a></h1><div class="epigraph"><p>空间不是被搜完的，是被扔完的；剪枝扔掉哪一类，哪一类就永远进不了候选——所以剪的依据必须比搜索本身更可靠。</p><footer>—— 据 Graefe and McKenna, ICDE 1993；Vance and Maier, 1996；Moerkotte and Neumann, DPCCP 整理</footer></div><p><a href="/cs/qo-statistics">上一课</a>把摘要子系统接好，枚举从此有了可信、也永远不够可信的输入。主干 <a href="/cs/selinger-dp">Selinger 动态规划</a> 给了子集 DP 与有趣序，<a href="/cs/join-order-space">连接顺序搜索空间</a> 画了左深、bushy 与连通限制。本课把「空间」当整体看：搜索的不只是连接顺序，算法选择、访问路径、并行度都挂在同一座 memo 上；枚举器的职责是组织等价计划，并安全地扔。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>空间是乘积。十张表的星型查询：左深排列约三百六十万，bushy 形状再乘上 Catalan 数到万亿量级；每个连接点还有哈希、归并、嵌套循环三种算法，每张表还有索引与堆两类访问路径。全部枚举不可能，于是两个问题：怎么组织，才不重复优化同一批等价子计划；怎么剪枝，才不把真最优扔掉。超时是常态而非异常：搜不完时交什么。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><span class="marginnote">memo 就是用「同一批等价子计划只存一份、只算一次」的手段来做「指数级空间去重」的事——可以把它想象成动态规划里的记忆化表格：键是子问题（等价类组），值是这个子问题当前已知的最好答案。</span>memo 组织：把表达式收进等价类组，组内装多个逻辑与物理表达式；变换规则（交换、结合、下推）在逻辑层生成等价类，实现规则把逻辑表达式替换成物理算子。新算子只需声明自己的实现规则与代价函数——第一课立过的接口——枚举器与规则互不相认，这是 Volcano 到 Cascades 一系优化器的封装口径。共享：bushy 树的两个分支若到达同一组，只算一次。剪枝用分支限界：维护当前全局最好代价作上界；对候选子计划算一个<strong>可证的下界</strong>（例如只计不可避免的顺序读页数），下界超上界即整支剪掉。下界必须保守——掺了启发式的下界可能剪掉真最优。启发式档位：表数超阈值换贪心或遗传搜索（GOO、IKKBZ 一族）；任意时间算法保证任何时刻可返回当前最佳。</p>',7)),(e(),n(A,null,{default:a(()=>[o(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOGIC%5B%22%E9%80%BB%E8%BE%91%E6%A0%91%22%5D%20--%3E%20EQ%5B%22%E5%8F%98%E6%8D%A2%E8%A7%84%E5%88%99%E7%94%9F%E6%88%90%E7%AD%89%E4%BB%B7%E7%B1%BB%22%5D%0A%20%20EQ%20--%3E%20MEMO%5B%22memo%20%E7%BB%84%E5%86%85%E5%85%B1%E4%BA%AB%E5%AD%90%E8%AE%A1%E5%88%92%22%5D%0A%20%20MEMO%20--%3E%20IMPL%5B%22%E5%AE%9E%E7%8E%B0%E8%A7%84%E5%88%99%EF%BC%9A%E7%AE%97%E6%B3%95%20%2F%20%E8%AE%BF%E9%97%AE%E8%B7%AF%E5%BE%84%22%5D%0A%20%20IMPL%20--%3E%20BB%5B%22%E5%88%86%E6%94%AF%E9%99%90%E7%95%8C%E5%89%AA%E6%9E%9D%22%5D%0A%20%20BB%20--%3E%20BEST%5B%22%E7%89%A9%E7%90%86%E6%9C%80%E4%BC%98%E8%AE%A1%E5%88%92%22%5D%0A%20%20BIG%5B%22%E8%A1%A8%E6%95%B0%E8%B6%85%E9%98%88%E5%80%BC%22%5D%20--%3E%20HEUR%5B%22%E8%B4%AA%E5%BF%83%20%2F%20%E9%81%97%E4%BC%A0%E6%90%9C%E7%B4%A2%22%5D%0A%20%20HEUR%20--%3E%20BEST%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=s("h2",{id:"机制",tabindex:"-1"},[B("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=s("p",null,"有趣序在这里归位：它是组内表达式的输出性质之一，比较按「性质加代价」做支配判定，不是单独一套空间。代价模型的可加性在此兑现：组的物理最优代价回填后，父组直接复用，不再重算——memo 的省时正来自第一课的分解要求。超时策略有个工程顺序：先跑贪心拿一个上界，再进精确搜索，剪枝立刻变强；这比「先精确、超时再退启发式」更划算。基数错误的阴影仍在：空间组织得再对，输入错了还是选错树——统计课从下、误差传播课从上，把这条边界夹住。",-1)),(e(),n(A,null,{default:a(()=>[o(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E6%90%9C%E7%B4%A2%E5%BC%80%E5%A7%8B%EF%BC%9A%E5%85%88%E8%B7%91%E8%B4%AA%E5%BF%83%22%5D%20--%3E%20UB%5B%22%E5%BD%93%E5%89%8D%E5%85%A8%E5%B1%80%E6%9C%80%E4%BC%98%E4%BB%A3%E4%BB%B7%20%3D%20%E4%B8%8A%E7%95%8C%22%5D%0A%20%20UB%20--%3E%20NODE%5B%22%E5%8F%96%E5%87%BA%E5%80%99%E9%80%89%E5%AD%90%E8%AE%A1%E5%88%92%22%5D%0A%20%20NODE%20--%3E%20LB%5B%22%E8%AE%A1%E7%AE%97%E5%8F%AF%E8%AF%81%E4%B8%8B%E7%95%8C%22%5D%0A%20%20LB%20--%3E%20CHECK%7B%22%E4%B8%8B%E7%95%8C%20%5Cgt%20%E4%B8%8A%E7%95%8C%EF%BC%9F%22%7D%0A%20%20CHECK%20--%3E%7C%E6%98%AF%7C%20CUT%5B%22%E6%95%B4%E6%94%AF%E5%89%AA%E6%8E%89%22%5D%0A%20%20CHECK%20--%3E%7C%E5%90%A6%7C%20DEEP%5B%22%E7%BB%A7%E7%BB%AD%E5%B1%95%E5%BC%80%22%5D%0A%20%20DEEP%20--%3E%20BETTER%7B%22%E5%87%BA%E7%8E%B0%E6%9B%B4%E4%BC%98%E5%AE%8C%E6%95%B4%E8%AE%A1%E5%88%92%EF%BC%9F%22%7D%0A%20%20BETTER%20--%3E%7C%E6%98%AF%7C%20UPD%5B%22%E4%B8%8A%E7%95%8C%E6%94%B6%E7%B4%A7%22%5D%0A%20%20UPD%20--%3E%20NODE%0A%20%20BETTER%20--%3E%7C%E5%90%A6%7C%20NODE%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">数字实例：上界已到 \\(120\\)，某子计划的可证下界是 \\(135\\)——即使后面全部按最省方式补全，这支也至少要 \\(135\\)，比 \\(120\\) 贵，整支扔掉不亏；但若下界掺了启发式、估成 \\(90\\)，真最优可能恰好藏在这支里被误剪。</span></p><p><span class="marginnote">初学者容易以为「先精确、超时再退启发式」更稳妥，实际上顺序反了：先跑贪心拿到一个够好的上界，精确搜索一进来就能大量剪枝，总时间往往更短——上界越紧，分支限界越锋利。</span></p><p><span class="marginnote">十表 bushy 形状数为 \\(\\mathrm{Catalan}(9)\\times 10!\\)，约 \\(1.8\\times 10^{13}\\)；PostgreSQL 在表数超过 <code>geqo_threshold</code>（默认十二）时改走遗传算法 GEQO——「精确 DP 让位启发式」是写进默认配置的工程决定。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>外连接的交换与结合带条件，规则合法性是代数问题，本课不展开——<a href="/cs/subquery-decorrelation">子查询去相关</a>课已见演算侧的防火墙。神经搜索不是主干：学习型优化器改变搜索的先验，不改变 memo 与剪枝的骨架。并行度作为计划维度引出 exchange，那是执行引擎课的地盘，本课只把它挂进空间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>空间是逻辑等价类加物理实现规则的乘积，memo 负责共享与去重。</li><li>剪枝依据可证下界；掺启发式的下界可能剪掉真最优。</li><li>有趣序是支配判定的维度，不是另一套空间。</li><li>超阈值换启发式是工程默认；先贪心后精确优于先精确后超时。</li><li>出处：Graefe and McKenna, 1993；Vance and Maier, 1996；Moerkotte and Neumann。</li></ul>',7))])}const _=l(p,[["render",m]]);export{T as __pageData,_ as default};
